                'address' => null,
                'address_line1' => 'Main Medical Avenue',
                'address_line2' => 'Jaipur',
                'city' => 'Jaipur',
                'state' => 'Rajasthan',
                'pincode' => null,
                'latitude' => null,
                'longitude' => null,
                'experience_years' => 0,
                'consultation_fee' => 0,
                'education_degrees' => [],
                'medical_council' => 'Medical Council of India',
                'registration_number' => 'REG-E29D336B90',
                'about_en' => 'Highly experienced specialist in General Surgeon practicing in Jaipur.',
                'about_hi' => 'जयपुर में अभ्यास करने वाले General Surgeon के अत्यधिक अनुभवी विशेषज्ञ डॉक्टर डॉ. अमित शरन।',
                'gender' => 'Unspecified',
                'phone' => null,
                'is_verified' => true,
            ],
        ];

        $liveDoctors = [];
        $allDoctors = $detailedDoctors;
        
        $unique = [];
        foreach ($allDoctors as $d) {
            $key = !empty($d['registration_number']) ? strtolower(trim($d['registration_number'])) : strtolower(trim($d['first_name'] . ' ' . $d['last_name']));
            $unique[$key] = $d;
        }
        $allDoctors = array_values($unique);

        [$allDoctors, $rejected] = self::filterDoctorRecords($allDoctors, $cityName);
        
        if (!empty($allDoctors)) {
            \App\Services\HealthcareSyncService::syncBatch($allDoctors, [], $cacheKey, 100, $cityName);
        } else if ($cacheKey) {
            \Illuminate\Support\Facades\Cache::put($cacheKey, ['status' => 'completed', 'city' => $cityName, 'progress' => 100, 'message' => "Doctor scraping completed for {$cityName}."], 300);
        }

        return $allDoctors;
    }

}